// "Make the todo list collaborative: just poll the server and save."
// This file SIMULATES the classic first attempt — poll + save the
// whole list — with two clients and an in-memory "server", so you
// can watch the lost update happen deterministically.
// Run it: node 68-collab-todo/original.js

// ---- the "server": the whole list, replaced on every save ----------
var serverList = [{ id: 1, title: "buy milk", done: false }];

function apiGet() { return JSON.parse(JSON.stringify(serverList)); }
function apiSave(list) { serverList = JSON.parse(JSON.stringify(list)); }

// ---- two browsers ---------------------------------------------------
// Problem 1: each client's copy is a snapshot from its last poll.
// Between polls it's stale, and neither client knows HOW stale.
var alice = apiGet();
var bob = apiGet();

// Alice adds a todo and saves THE WHOLE LIST:
alice.push({ id: 2, title: "alice: call the bank", done: false });
apiSave(alice);
console.log("after alice saves:", serverList.map(function (t) { return t.title; }));

// Bob — still holding the OLD snapshot — ticks off "buy milk" and
// saves HIS whole list...
bob[0].done = true;
apiSave(bob);

// Problem 2 — THE LOST UPDATE: bob's save replaced the whole list
// with his stale copy. Alice's todo is gone. No error, no conflict
// message, nothing. She'll notice on her next poll... 2 seconds of
// confusion, then "this app eats my todos".
console.log("after bob saves:  ", serverList.map(function (t) { return t.title; }));
console.log("alice's todo just vanished — no error anywhere.");

// Problem 3: polling every 2s means up to 2s of lag for OTHER
// people's changes and a constant GET drumbeat for nothing. Project
// 67 built the push pipe this app should be using.

// Problem 4: "save the whole list" makes every write a total
// overwrite, so conflicts are guaranteed to destroy data. The finer
// the writes (one operation per change), the smaller the blast
// radius — that's most of the fix, before any clever merging.

# 🏋️ Practice: Collaborative Todo List

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. pendingCount (warm-up)

Write `pendingCount(state)` returning how many todos are still optimistic placeholders (`pending: true`) — the number the page could show as "syncing…". Check: two `optimisticAdd`s give a count of 2; after `applyEvent` confirms one of them (its `originTag` in `myTags`), the count drops to 1; `initialState()` gives 0.

What it practices: reading the state shape — pending is a visible state, so it should be countable.

Hint: `filter` on the `pending` flag, then `.length`.

### ⭐⭐ 2. optimisticDelete (core)

`sync.js` has `optimisticAdd` and `optimisticToggle` but no delete. Write `optimisticDelete(state, id)` — pure, immutable — that removes the row instantly. Simplest correct design: just filter it out; if the server later rejects the write, rollback is "re-sync from the log," so no tombstone bookkeeping is needed. Check: the row disappears from the new state while the *old* state still contains it, and when the server's `{ type: 'deleted' }` echo arrives, `applyEvent` leaves the list empty and advances `version`.

What it practices: extending the optimistic layer in the file's own style — new state out, old state kept for rollback.

Hint: `state.todos.filter((t) => t.id !== id)`, spread the rest.

### ⭐⭐ 3. Deleting a ghost — version must still advance (core)

Add a test for an edge `sync.test.js` skips: a `deleted` event for an id this client never had (someone else added *and* deleted it while you were offline, and your `?since=` replay starts after the add… or the log was compacted). Assert the todos are untouched **and** `state.version` still becomes the event's version — then prove why it matters by applying a following version-3 upsert and asserting it lands rather than being treated as out of sequence.

What it practices: the invariant that version tracks *events processed*, not *rows changed*.

Hint: `applyEvent` runs the delete branch before any "did we have it?" check — `filter` on a missing id is a no-op that still returns `{ todos, version: event.version }`.

### ⭐⭐ 4. planFor — spotting a gap in the stream (core)

Events arrive numbered, so a client can *detect* lost messages: write `planFor(state, event)` returning `'ignore'` when `event.version <= state.version` (stale/duplicate), `'apply'` when it's exactly `state.version + 1`, and `'resync'` when it jumps further ahead — meaning events were missed and the client should refetch `/events?since=`. Check all five: state at version 3 with events versioned 2, 3, 4, 6 → `ignore`, `ignore`, `apply`, `resync`; a fresh client seeing version 1 → `apply`.

What it practices: turning the versioned log into a self-diagnosing stream — the same `?since=` idea, driven from the client side.

Hint: three comparisons, in the order stale → next → gap.

### ⭐⭐⭐ 5. Compact the log (challenge)

A server that never restarts grows its log forever, yet a *new* client only needs enough events to rebuild the current list. Write `compact(log)` producing a minimal equivalent log: for each id keep only the **latest** upsert, drop upserts whose todo was later deleted, drop the delete events themselves (a fresh client can't have the row anyway), and renumber versions 1…n. Prove equivalence: `applyEvents(initialState(), compact(log))` must yield **exactly the same `todos` array** (same order!) as replaying the full log — including a log where a todo is deleted and then re-added under the same id. Also check: an empty log and an everything-deleted log both compact to `[]`.

What it practices: the log-vs-state duality — compaction is deriving the minimal history that produces the same state.

Hint: one pass with a `Map` from id → latest upsert, calling `.delete(id)` on deletes; a `Map` keeps first-insertion order, and re-adding after a delete moves the id to the end — exactly matching full-replay order.

### ⭐⭐⭐ 6. flushOutbox — writes queued while offline (challenge)

LEARN.md's kill-the-server experiment shows writes just fail while disconnected. Design the fix's core: an outbox array of queued operations and `async flushOutbox(outbox, send)` that sends them **in order**, one at a time (`await` each), stops at the first `send` that resolves `false` (still offline), and returns the array of operations not yet sent — without mutating the input. Check with fakes: an always-true `send` receives ops in order and returns `[]`; a `send` failing on the second call leaves ops 2 and 3 queued in order; flushing the returned remainder with a working `send` drains it.

What it practices: retry-friendly queue logic — pure enough to test with a fake `send`, exactly like the server tests fake a browser.

Hint: copy the array, `while` it's non-empty `await send(remaining[0])`, `shift()` on success, `break` on failure.

## Solutions

### 1. pendingCount

```js
export function pendingCount(state) {
  return state.todos.filter((t) => t.pending).length;
}
```

WHY: The refactor's rule is that *pending* is a real, visible state — placeholder rows render dimmed — so it must be derivable from state, not scattered in DOM classes. Confirmed rows lose the flag when `applyEvent` swaps in the server's todo, so the count falls to zero exactly when the client is fully in sync: a free "all changes saved" indicator.

### 2. optimisticDelete

```js
export function optimisticDelete(state, id) {
  return { ...state, todos: state.todos.filter((t) => t.id !== id) };
}
```

WHY: It follows the file's contract — new state out, input untouched — so the pre-delete state remains available, and true rollback is "rebuild from the log," the same answer as every other rejection. No `pending` tombstone is needed because the server's `deleted` echo finds the row already gone: `filter` on an absent id changes nothing, and only the version advances. Removal being idempotent is what makes optimistic-then-confirm safe here without originTag gymnastics.

### 3. The ghost-delete test

```js
test('deleting an id we never had: list untouched, version still advances', () => {
  const seed = { version: 1, type: 'upsert', originTag: 's', todo: { id: 1, title: 'a', done: false } };
  let s = applyEvent(initialState(), seed, new Set());
  s = applyEvent(s, { version: 2, type: 'deleted', originTag: 'x', todoId: 99 }, new Set());
  assert.deepEqual(s.todos.map((t) => t.title), ['a']);
  assert.equal(s.version, 2); // the invariant under test
  // and the stream keeps flowing — version 3 is not "out of sequence":
  s = applyEvent(s, { version: 3, type: 'upsert', originTag: 'y', todo: { id: 2, title: 'b', done: false } }, new Set());
  assert.deepEqual(s.todos.map((t) => t.title), ['a', 'b']);
});
```

WHY: `version` means "I have processed the log up to here" — it must advance for every accepted event, even ones that change no rows. If a ghost delete left `version` at 1, this client would *ignore* nothing (later events still exceed it) but any gap-detection or `?since=` logic would silently mis-report; the follow-up upsert assertion makes the consequence concrete instead of theoretical.

### 4. planFor

```js
export function planFor(state, event) {
  if (event.version <= state.version) return 'ignore';
  if (event.version === state.version + 1) return 'apply';
  return 'resync';
}
```

WHY: The numbered log makes the stream self-describing: any client can classify an incoming event with two comparisons, no server round-trip. `applyEvent` already survives stale events, but a *jump* means missed history that no local logic can invent — the only honest response is refetching `/events?since=`, and this function is the decision point the reconnect path already implements implicitly.

### 5. compact

```js
export function compact(log) {
  const lastUpsert = new Map(); // id -> latest surviving upsert
  for (const event of log) {
    if (event.type === 'deleted') lastUpsert.delete(event.todoId);
    else lastUpsert.set(event.todo.id, event);
  }
  return [...lastUpsert.values()].map((event, i) => ({ ...event, version: i + 1 }));
}
```

WHY: Compaction works because state is a *fold* over the log — any shorter log with the same fold result is equivalent for a fresh client, and "latest upsert per surviving id" is the minimal such log. The `Map` earns its place with ordering: it remembers first-insertion position for updated keys, and `delete` + re-`set` moves a re-added id to the end — both matching exactly how `applyEvent` orders the todos array during a full replay, which is why the same-order assertion passes. Real systems (Kafka compaction, Redux snapshotting) ship this exact idea; renumbering only works for a *fresh* client, since existing clients' versions refer to the old numbering.

### 6. flushOutbox

```js
export async function flushOutbox(outbox, send) {
  const remaining = [...outbox];
  while (remaining.length > 0) {
    const ok = await send(remaining[0]);
    if (!ok) break; // still offline — keep the rest, in order
    remaining.shift();
  }
  return remaining;
}
```

WHY: Order is the whole game — the server assigns versions in arrival order, so flushing out of order could commit "toggle" before the "add" it targets; one-at-a-time `await` preserves the user's intent sequence. Stopping at the first failure (rather than skipping ahead) keeps the queue a clean prefix-drained structure, and returning the remainder instead of mutating lets the caller retry later with the same function — the same "return the new value, keep the old" discipline as every pure function in `sync.js`. Fake `send` functions make all three behaviors testable offline, mirroring how `server.test.js` fakes a browser.

/**
 * The collaboration server = three earlier projects composed:
 *
 *   project 65's framework  -> the HTTP API (POST/PUT/DELETE todos)
 *   project 67's protocol   -> the WebSocket push pipe
 *   an EVENT LOG            -> the single source of truth
 *
 * Every mutation appends { version, type, todo, originTag } to the
 * log and broadcasts it. New/reconnecting clients say which version
 * they have (?since=N) and get a replay. Writes are fine-grained
 * operations, never "save the whole list" — small blast radius.
 *
 *   node 68-collab-todo/refactored/server.js
 *   -> open http://localhost:3000 in TWO windows; edit in both.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createApp, jsonBody, HttpError } from '../../65-rest-api/refactored/app.js';
import { upgradeResponse } from '../../67-websocket-chat/refactored/handshake.js';
import { decodeFrames, encodeText, encodeFrame, OPCODES } from '../../67-websocket-chat/refactored/frames.js';

export function createCollabServer(port = 0) {
  // ---- truth: todos + the event log --------------------------------
  const todos = new Map();
  const eventLog = [];
  let nextId = 1;
  const sockets = new Set();

  function commit(type, data, originTag) {
    const event = { version: eventLog.length + 1, type, ...data, originTag };
    eventLog.push(event);
    const frame = encodeText(JSON.stringify(event));
    for (const s of sockets) s.write(frame); // push beats polling (project 67)
    return event;
  }

  // ---- the HTTP API (project 65's layering, compressed) ------------
  const app = createApp();
  app.use(jsonBody());

  app.get('/', (ctx) => {
    ctx.res.writeHead(200, { 'Content-Type': 'text/html' });
    ctx.res.end(fs.readFileSync(
      path.join(path.dirname(fileURLToPath(import.meta.url)), 'index.html')));
  });

  app.get('/events', (ctx) => {
    const since = Number(ctx.query.get('since') ?? 0);
    ctx.json(200, eventLog.filter((e) => e.version > since));
  });

  app.post('/todos', (ctx) => {
    const { title, originTag } = ctx.body ?? {};
    if (typeof title !== 'string' || !title.trim()) {
      throw new HttpError(400, 'title must be a non-empty string');
    }
    const todo = { id: nextId++, title: title.trim().slice(0, 200), done: false };
    todos.set(todo.id, todo);
    ctx.json(201, commit('upsert', { todo }, originTag));
  });

  app.put('/todos/:id', (ctx) => {
    const id = Number(ctx.params.id);
    const existing = todos.get(id);
    if (!existing) throw new HttpError(404, `no todo ${id}`);
    const todo = { ...existing, done: !!ctx.body?.done };
    todos.set(id, todo);
    ctx.json(200, commit('upsert', { todo }, ctx.body?.originTag));
  });

  app.delete('/todos/:id', (ctx) => {
    const id = Number(ctx.params.id);
    if (!todos.delete(id)) throw new HttpError(404, `no todo ${id}`);
    ctx.json(200, commit('deleted', { todoId: id }, ctx.body?.originTag));
  });

  // ---- the push pipe (project 67's protocol) ------------------------
  const server = app.listen(port);
  server.on('upgrade', (req, socket) => {
    socket.write(upgradeResponse(req.headers['sec-websocket-key']));
    sockets.add(socket);

    // catch-up replay: the client tells us the last version it saw
    const since = Number(new URL(req.url, 'http://x').searchParams.get('since') ?? 0);
    for (const event of eventLog.filter((e) => e.version > since)) {
      socket.write(encodeText(JSON.stringify(event)));
    }

    let pending = Buffer.alloc(0);
    socket.on('data', (chunk) => {
      let frames;
      try {
        ({ frames, rest: pending } = decodeFrames(Buffer.concat([pending, chunk])));
      } catch { return socket.destroy(); }
      for (const frame of frames) {
        if (frame.opcode === OPCODES.CLOSE) {
          socket.write(encodeFrame(OPCODES.CLOSE, frame.payload));
          socket.end();
        } else if (frame.opcode === OPCODES.PING) {
          socket.write(encodeFrame(OPCODES.PONG, frame.payload));
        }
        // clients never send edits over the socket: WRITES go through
        // HTTP (validated, error-shaped); the socket is a read-only
        // firehose. One door per direction.
      }
    });
    const drop = () => sockets.delete(socket);
    socket.on('close', drop);
    socket.on('error', drop);
  });

  return server;
}

if (import.meta.url === `file:///${process.argv[1].replace(/\\/g, '/')}`) {
  const server = createCollabServer(3000);
  server.on('listening', () =>
    console.log('collab todos at http://localhost:3000 — open two windows'));
}

// Integration: the composed system, exercised end to end. The "browser"
// here is project 67's own frame codec riding a raw TCP socket — the
// protocol we built is now our test tool.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import net from 'node:net';
import { createCollabServer } from './server.js';
import { decodeFrames, OPCODES } from '../../67-websocket-chat/refactored/frames.js';

let server, port, base;

before(async () => {
  server = createCollabServer(0);
  await new Promise((r) => server.on('listening', r));
  port = server.address().port;
  base = `http://localhost:${port}`;
});

after(() => server.close());

const post = (path, body) => fetch(base + path, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body),
});

/** A minimal WebSocket client: handshake, then collect text frames. */
function wsClient(since = 0) {
  return new Promise((resolve) => {
    const socket = net.connect(port, 'localhost', () => {
      socket.write([
        `GET /?since=${since} HTTP/1.1`, `Host: localhost:${port}`,
        'Upgrade: websocket', 'Connection: Upgrade',
        'Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==', 'Sec-WebSocket-Version: 13',
        '', '',
      ].join('\r\n'));
    });

    const events = [];
    let pending = Buffer.alloc(0);
    let upgraded = false;

    socket.on('data', (chunk) => {
      if (!upgraded) {
        const text = chunk.toString();
        const headerEnd = text.indexOf('\r\n\r\n');
        assert.match(text, /101 Switching Protocols/);
        upgraded = true;
        chunk = chunk.subarray(Buffer.byteLength(text.slice(0, headerEnd + 4)));
      }
      const out = decodeFrames(Buffer.concat([pending, chunk]));
      pending = out.rest;
      for (const f of out.frames) {
        if (f.opcode === OPCODES.TEXT) events.push(JSON.parse(f.payload.toString()));
      }
    });

    setTimeout(() => resolve({ events, close: () => socket.destroy() }), 150);
  });
}

test('a mutation over HTTP is pushed to a connected WebSocket client', async () => {
  const client = await wsClient(); // connected before the change
  await post('/todos', { title: 'first shared todo', originTag: 't1' });
  await new Promise((r) => setTimeout(r, 100)); // let the frame arrive

  const upserts = client.events.filter((e) => e.type === 'upsert');
  assert.ok(upserts.some((e) => e.todo.title === 'first shared todo'));
  assert.equal(upserts.at(-1).originTag, 't1'); // tags echo back for reconciliation
  client.close();
});

test('late joiners catch up via ?since= replay', async () => {
  await post('/todos', { title: 'made before you arrived', originTag: 't2' });
  const client = await wsClient(0); // connects AFTER the change
  assert.ok(client.events.some((e) => e.todo?.title === 'made before you arrived'));
  client.close();
});

test('the /events endpoint serves the same log over plain HTTP', async () => {
  const all = await (await fetch(`${base}/events?since=0`)).json();
  assert.ok(all.length >= 2);
  assert.deepEqual(all.map((e) => e.version), all.map((_, i) => i + 1)); // 1,2,3... no gaps
  const since = await (await fetch(`${base}/events?since=${all.length - 1}`)).json();
  assert.equal(since.length, 1); // only what you're missing
});

test('validation still guards the door (project 65 lives on)', async () => {
  const res = await post('/todos', { title: '' });
  assert.equal(res.status, 400);
  assert.ok((await res.json()).error);
});

/**
 * The client's sync brain — pure functions, aggressively tested,
 * because "two browsers editing the same list" is where bugs breed.
 *
 * The architecture (server-authoritative event log):
 *
 *   - The SERVER owns truth: every change becomes a numbered EVENT
 *     { version, type, todo, originTag } broadcast to all clients.
 *   - Clients apply their own edits OPTIMISTICALLY (instant UI),
 *     tagged with a random originTag.
 *   - Every client's state is rebuilt from events IN SERVER ORDER —
 *     including your own edits, which come back to you through the
 *     same pipe as everyone else's. One code path, guaranteed
 *     convergence: same events, same order, same final state.
 *   - originTag lets a returning event REPLACE your optimistic
 *     placeholder instead of duplicating it.
 *
 * Conflicts resolve last-write-wins in server order — honest and
 * simple. (Real-time text needs OT/CRDTs; a todo list does not.)
 */

export function initialState() {
  return { todos: [], version: 0 };
}

/** Your own edit, applied instantly, marked as not-yet-confirmed. */
export function optimisticAdd(state, { tag, title }) {
  return {
    ...state,
    todos: [...state.todos, { id: `pending-${tag}`, title, done: false, pending: true }],
  };
}

export function optimisticToggle(state, id) {
  return {
    ...state,
    todos: state.todos.map((t) => (t.id === id ? { ...t, done: !t.done, pending: true } : t)),
  };
}

/**
 * The single entry point for server truth. Handles, in order:
 *   - stale/duplicate events (version <= ours): ignored
 *   - an event echoing OUR optimistic edit (originTag match):
 *     the placeholder is replaced in place — no duplicate, no flicker
 *   - everyone else's events: upsert/delete by id
 */
export function applyEvent(state, event, myTags = new Set()) {
  if (event.version <= state.version) return state; // replays are harmless

  let todos;
  if (event.type === 'deleted') {
    todos = state.todos.filter((t) => t.id !== event.todoId);
  } else if (myTags.has(event.originTag)) {
    // our own edit, confirmed: swap the placeholder for the real row
    const placeholderId = `pending-${event.originTag}`;
    let replaced = false;
    todos = state.todos.map((t) => {
      if (t.id === placeholderId || t.id === event.todo.id) {
        replaced = true;
        return event.todo;
      }
      return t;
    });
    if (!replaced) todos = [...todos, event.todo];
    // a toggle-confirm can produce two rows with the same id — dedupe:
    todos = todos.filter((t, i) => todos.findIndex((u) => u.id === t.id) === i);
  } else {
    const exists = state.todos.some((t) => t.id === event.todo.id);
    todos = exists
      ? state.todos.map((t) => (t.id === event.todo.id ? event.todo : t))
      : [...state.todos, event.todo];
  }

  return { todos, version: event.version };
}

/** Reconnect catch-up: replay everything after our version. */
export function applyEvents(state, events, myTags) {
  return events.reduce((s, e) => applyEvent(s, e, myTags), state);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  initialState, optimisticAdd, optimisticToggle, applyEvent, applyEvents,
} from './sync.js';

const titles = (s) => s.todos.map((t) => t.title);

test('optimistic add shows instantly, marked pending', () => {
  const s = optimisticAdd(initialState(), { tag: 'a1', title: 'call the bank' });
  assert.deepEqual(titles(s), ['call the bank']);
  assert.equal(s.todos[0].pending, true);
});

test('our own event replaces the placeholder — no duplicate, no flicker', () => {
  let s = optimisticAdd(initialState(), { tag: 'a1', title: 'call the bank' });
  s = applyEvent(s, {
    version: 1, type: 'upsert', originTag: 'a1',
    todo: { id: 7, title: 'call the bank', done: false },
  }, new Set(['a1']));
  assert.deepEqual(s.todos, [{ id: 7, title: 'call the bank', done: false }]);
  assert.equal(s.version, 1);
});

test("someone ELSE's event upserts by id", () => {
  let s = applyEvent(initialState(), {
    version: 1, type: 'upsert', originTag: 'bob-1',
    todo: { id: 1, title: 'buy milk', done: false },
  }, new Set());
  s = applyEvent(s, {
    version: 2, type: 'upsert', originTag: 'bob-2',
    todo: { id: 1, title: 'buy milk', done: true },
  }, new Set());
  assert.deepEqual(s.todos, [{ id: 1, title: 'buy milk', done: true }]);
});

test('stale and duplicate events are ignored (replays are harmless)', () => {
  const e1 = { version: 1, type: 'upsert', originTag: 'x', todo: { id: 1, title: 'a', done: false } };
  let s = applyEvent(initialState(), e1, new Set());
  const again = applyEvent(applyEvent(s, e1, new Set()), e1, new Set());
  assert.deepEqual(again, s);
});

test("THE ORIGINAL'S LOST UPDATE, FIXED: alice's add and bob's toggle both survive", () => {
  // server order: alice's add is version 2, bob's toggle version 3
  const events = [
    { version: 1, type: 'upsert', originTag: 'seed', todo: { id: 1, title: 'buy milk', done: false } },
    { version: 2, type: 'upsert', originTag: 'alice-1', todo: { id: 2, title: 'alice: call the bank', done: false } },
    { version: 3, type: 'upsert', originTag: 'bob-1', todo: { id: 1, title: 'buy milk', done: true } },
  ];

  // alice saw her own add optimistically first; bob toggled optimistically first
  let alice = applyEvent(initialState(), events[0], new Set());
  alice = optimisticAdd(alice, { tag: 'alice-1', title: 'alice: call the bank' });
  alice = applyEvents(alice, events.slice(1), new Set(['alice-1']));

  let bob = applyEvent(initialState(), events[0], new Set());
  bob = optimisticToggle(bob, 1);
  bob = applyEvents(bob, events.slice(1), new Set(['bob-1']));

  // CONVERGENCE: same events, same order -> identical state, nothing lost
  assert.deepEqual(alice.todos, bob.todos);
  assert.deepEqual(titles(alice).sort(), ['alice: call the bank', 'buy milk']);
  assert.equal(alice.todos.find((t) => t.id === 1).done, true);
});

test('true conflict: two clients toggle the same todo — last write wins, both agree', () => {
  const seed = { version: 1, type: 'upsert', originTag: 's', todo: { id: 1, title: 'x', done: false } };
  // both toggles hit the server; server orders them: done:true then done:false
  const events = [
    { version: 2, type: 'upsert', originTag: 'a', todo: { id: 1, title: 'x', done: true } },
    { version: 3, type: 'upsert', originTag: 'b', todo: { id: 1, title: 'x', done: false } },
  ];
  const a = applyEvents(applyEvent(initialState(), seed, new Set()), events, new Set(['a']));
  const b = applyEvents(applyEvent(initialState(), seed, new Set()), events, new Set(['b']));
  assert.deepEqual(a.todos, b.todos); // they disagree with ONE user's intent,
  assert.equal(a.todos[0].done, false); // but never with each other
});

test('delete events remove; catch-up replay after reconnect works from any version', () => {
  const log = [
    { version: 1, type: 'upsert', originTag: 'x', todo: { id: 1, title: 'a', done: false } },
    { version: 2, type: 'upsert', originTag: 'x', todo: { id: 2, title: 'b', done: false } },
    { version: 3, type: 'deleted', originTag: 'x', todoId: 1 },
  ];
  // a client that disconnected after version 1 replays 2..3:
  let s = applyEvent(initialState(), log[0], new Set());
  s = applyEvents(s, log.filter((e) => e.version > s.version), new Set());
  assert.deepEqual(titles(s), ['b']);
  assert.equal(s.version, 3);
});
